type Milestone = { id:number; code:string; name:string; description?:string; planned_visits:number;planned_mandays?:string|null;assigned_consultants?:number;estimated_working_days?:string|null;amount?:string|null;payment_percent?:string|null;payment_status?:string|null;activities?:string[];responsible_consultant_id?:number|null; responsible_consultant_name?:string|null;consultant_allocations?:{consultant_id:number;consultant_name:string;allocated_mandays:string}[]; actual_visits:number; progress:string; status:string; start_date?:string|null; closing_date?:string|null; payment_date?:string|null; portal_report_submission_date?:string|null };
